function startSeriesGame() {
  document.getElementById('game-series').style.display = 'block';
  games.series = { score: 0, streak: 0, timeLeft: 30, timer: null };
  document.getElementById('series-score').textContent = '0';
  document.getElementById('series-streak').textContent = '0';
  document.getElementById('series-feedback').textContent = '';
  document.getElementById('series-feedback').className = 'feedback';
  nextSeriesQuestion();
  startTimer('series');
}

function nextSeriesQuestion() {
  const g = games.series;
  if (!g) return;

  // Pick two resistor values from a nice set
  const niceValues = [10, 22, 33, 47, 56, 68, 82, 100, 120, 150, 200, 220, 330, 470, 560, 680, 820, 1000, 1200, 1500, 2000, 2200, 3300, 4700, 5600, 10000];
  const r1 = niceValues[Math.floor(Math.random() * niceValues.length)];
  let r2 = niceValues[Math.floor(Math.random() * niceValues.length)];
  while (r2 === r1) r2 = niceValues[Math.floor(Math.random() * niceValues.length)];

  const isSeries = Math.random() > 0.5;
  const connection = isSeries ? 'series' : 'parallel';

  let correctAnswer, questionText;

  if (isSeries) {
    correctAnswer = r1 + r2;
    questionText = 'What is the total resistance?';
  } else {
    correctAnswer = (r1 * r2) / (r1 + r2);
    questionText = 'What is the total resistance?';
  }

  // Format correct answer
  const correctText = formatResistance(Math.round(correctAnswer * 100) / 100);

  document.getElementById('series-question').textContent = questionText;
  document.getElementById('series-given').innerHTML =
    '<div class="val">R₁ = <span>' + r1 + 'Ω</span></div>' +
    '<div class="val">R₂ = <span>' + r2 + 'Ω</span></div>' +
    '<div class="val">Connection: <span>' + (isSeries ? '🔗 Series' : '⚡ Parallel') + '</span></div>';

  // Generate wrong choices
  let choices = [correctText];

  // Add the "other" calculation as a distractor
  const otherAnswer = isSeries ? (r1 * r2) / (r1 + r2) : (r1 + r2);
  const otherText = formatResistance(Math.round(otherAnswer * 100) / 100);
  if (otherText !== correctText) choices.push(otherText);

  // Add a few more wrong values
  while (choices.length < 4) {
    const wrongVal = correctAnswer * (0.5 + Math.random() * 1.5);
    const wrongText = formatResistance(Math.round(wrongVal * 100) / 100);
    if (!choices.includes(wrongText) && wrongText !== correctText) choices.push(wrongText);
  }

  choices.sort(() => Math.random() - 0.5);
  g.currentAnswer = correctText;

  const choicesDiv = document.getElementById('series-choices');
  choicesDiv.innerHTML = '';
  choices.forEach(c => {
    const btn = document.createElement('button');
    btn.className = 'choice-btn';
    btn.textContent = c;
    btn.onclick = () => checkSeries(btn, c);
    choicesDiv.appendChild(btn);
  });

  document.getElementById('series-feedback').textContent = '';
  document.getElementById('series-feedback').className = 'feedback';
}

